create table computers (id bigserial primary key, agent_id varchar(120) not null unique, hostname varchar(255) not null, operating_system varchar(255), os_version varchar(255), architecture varchar(100), status varchar(20) not null default 'UNKNOWN', last_seen timestamptz, registered_at timestamptz not null, ip_address varchar(80), mac_address varchar(80), agent_version varchar(80));
create index idx_computers_agent_id on computers(agent_id); create index idx_computers_status on computers(status); create index idx_computers_last_seen on computers(last_seen);
create table hardware_inventory (id bigserial primary key, computer_id bigint not null unique references computers(id) on delete cascade, cpu_manufacturer varchar(255), cpu_model varchar(500), physical_cores integer, logical_cores integer, cpu_frequency bigint, ram_total bigint, gpu_name varchar(500), gpu_vendor varchar(255), gpu_memory bigint, motherboard_manufacturer varchar(255), motherboard_model varchar(255), bios_version varchar(255), storage_information text, updated_at timestamptz not null);
create table telemetry (id bigserial primary key, computer_id bigint not null references computers(id) on delete cascade, timestamp timestamptz not null, cpu_usage numeric(6,2), cpu_temperature numeric(6,2), ram_total bigint, ram_used bigint, ram_available bigint, ram_usage numeric(6,2), storage_total bigint, storage_used bigint, storage_free bigint, storage_usage numeric(6,2), gpu_usage numeric(6,2), gpu_temperature numeric(6,2), network_status varchar(40), network_download bigint, network_upload bigint, process_count integer, uptime bigint);
create index idx_telemetry_computer_timestamp on telemetry(computer_id,timestamp desc);
create table heartbeats (id bigserial primary key, computer_id bigint not null references computers(id) on delete cascade, timestamp timestamptz not null, agent_version varchar(80), ip_address varchar(80), status varchar(40)); create index idx_heartbeats_computer_timestamp on heartbeats(computer_id,timestamp desc);
create table faults (id bigserial primary key, computer_id bigint not null references computers(id) on delete cascade, type varchar(80) not null, severity varchar(20) not null, message varchar(1000) not null, metric varchar(80), current_value numeric(12,2), threshold numeric(12,2), detected_at timestamptz not null, resolved_at timestamptz, status varchar(20) not null); create index idx_faults_computer_status on faults(computer_id,status); create index idx_faults_severity on faults(severity); create index idx_faults_detected_at on faults(detected_at desc);
create table reports (id bigserial primary key, computer_id bigint not null references computers(id) on delete cascade, report_type varchar(50) not null, title varchar(255) not null, description text, severity varchar(20), created_at timestamptz not null, resolved_at timestamptz, status varchar(20) not null, generated_by varchar(80) not null); create index idx_reports_computer_created on reports(computer_id,created_at desc); create index idx_reports_status on reports(status);
